package com.qpay.payment.application;
import com.qpay.payment.domain.UtilityPaymentStatus;import com.qpay.payment.infrastructure.UtilityPaymentRepository;import com.qpay.payment.provider.UtilityProvider;import com.qpay.payment.wallet.UtilityWalletClient;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;import java.math.BigInteger;import java.util.*;
@Service public class UtilityPaymentService {
 private final UtilityPaymentRepository repo;private final UtilityWalletClient wallet;private final UtilityProvider provider;private final TransactionTemplate tx;private final int feeBps;public UtilityPaymentService(UtilityPaymentRepository repo,UtilityWalletClient wallet,UtilityProvider provider,TransactionTemplate tx,@Value("${qpay.utility.fee-basis-points:50}")int feeBps){this.repo=repo;this.wallet=wallet;this.provider=provider;this.tx=tx;this.feeBps=feeBps;}
 public UtilityPaymentView create(UUID merchant,UUID walletId,String reference,String biller,String consumer,long amount,Currency currency){if(amount<=0)throw new IllegalArgumentException("utility amount must be positive");long fee=BigInteger.valueOf(amount).multiply(BigInteger.valueOf(feeBps)).divide(BigInteger.valueOf(10000)).longValueExact();var reservation=tx.execute(s->repo.create(merchant,walletId,reference,biller,consumer,amount,fee,currency.getCurrencyCode()));if(reservation.replay())return reservation.payment();var p=reservation.payment();UUID hold=wallet.hold(walletId,p.id().toString(),Math.addExact(amount,fee),currency.getCurrencyCode());try{tx.execute(s->repo.transition(p.id(),UtilityPaymentStatus.CREATED,UtilityPaymentStatus.FUNDS_HELD,hold,null,null));}catch(RuntimeException e){wallet.release(hold);throw e;}var result=provider.submit(new UtilityProvider.Request(p.id(),biller,consumer,amount,currency));if(!result.succeeded()){tx.execute(s->repo.transition(p.id(),UtilityPaymentStatus.FUNDS_HELD,UtilityPaymentStatus.FAILED,hold,result.providerReference(),result.failureCode()));wallet.release(hold);return tx.execute(s->repo.transition(p.id(),UtilityPaymentStatus.FAILED,UtilityPaymentStatus.FUNDS_RELEASED,hold,null,result.failureCode()));}tx.execute(s->repo.transition(p.id(),UtilityPaymentStatus.FUNDS_HELD,UtilityPaymentStatus.SUBMITTED,hold,result.providerReference(),null));wallet.settle(hold,p.id(),amount,fee,currency.getCurrencyCode());return tx.execute(s->repo.transition(p.id(),UtilityPaymentStatus.SUBMITTED,UtilityPaymentStatus.SUCCEEDED,hold,null,null));}
 public UtilityPaymentView get(UUID id){return repo.find(id).orElseThrow(()->new IllegalArgumentException("utility payment not found"));}
}
